(()=>{
const purple='#7255a4',green='#2f8f6b',red='#bb6c53',grey='#8b8c87';
function svg(inner,desc){return `<svg class="diagram" viewBox="0 0 640 390" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${desc}"><title>${desc}</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${grey}"/></marker></defs>${inner}</svg>`}
const txt=(x,y,t,c='#50534d',size=13)=>`<text x="${x}" y="${y}" fill="${c}" font-size="${size}" font-family="system-ui,sans-serif">${t}</text>`;
function axes(yLabel='Expenditure / output',xLabel='Income / output (Y)'){return `<path d="M65 30V330H610" fill="none" stroke="${grey}" stroke-width="1.5" marker-start="url(#arrow)" marker-end="url(#arrow)"/>${txt(40,350,'0')}${txt(390,375,xLabel)}${txt(70,18,yLabel)}`}
function line(x1,y1,x2,y2,color,dash=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2.5" ${dash?'stroke-dasharray="'+dash+'"':''}/>`}
function point(x,y,label){return `<circle cx="${x}" cy="${y}" r="5" fill="${purple}"/>${txt(x+9,y-10,label,purple)}`}
function curve(a,b,max,xmax=1000,color=purple){return line(65,330-280*a/max,605,330-280*(a+b*xmax)/max,color)}
function demand(a=100,b=.75,I=100,Yf=800,gap=false){let eq=(a+I)/(1-b),maxY=Math.max(eq,Yf)*1.25,max=Math.max(a+I+b*maxY,maxY)*1.1;const x=Y=>65+540*Y/maxY,y=V=>330-280*V/max;let s=axes();s+=line(65,330,x(maxY),y(maxY),grey);s+=txt(x(maxY)-75,y(maxY)-10,'AS = Y',grey);s+=line(65,y(a+I),x(maxY),y(a+I+b*maxY),purple);s+=txt(x(maxY)-95,y(a+I+b*maxY)-13,'AD = C + I',purple);if(eq<=maxY){s+=point(x(eq),y(eq),'E');s+=line(x(eq),y(eq),x(eq),330,grey,'4 5')+txt(x(eq)-20,351,'Y* = '+Math.round(eq))}if(gap){let ad=a+I+b*Yf;s+=line(x(Yf),y(Math.max(ad,Yf)),x(Yf),330,grey,'4 5');s+=line(x(Yf),y(ad),x(Yf),y(Yf),red);s+=point(x(Yf),y(Yf),'Full employment');s+=txt(x(Yf)+10,(y(ad)+y(Yf))/2,'Gap = '+Math.round(Math.abs(ad-Yf)),red);s+=txt(x(Yf)-10,368,'Yf')}return svg(s,'AD–AS diagram: aggregate expenditure and output, with equilibrium at their intersection. '+(gap?'The demand gap is measured vertically at full-employment output.':''))}
function consumption(a=80,b=.75){let be=a/(1-b),mx=Math.max(800,be*1.4),max=a+mx;const x=Y=>65+540*Y/mx,y=V=>330-280*V/max;let s=axes('Consumption (C)','Income (Y)');s+=line(65,330,x(mx),y(mx),grey)+txt(x(mx)-75,y(mx)-10,'C = Y',grey);s+=line(65,y(a),x(mx),y(a+b*mx),purple)+txt(400,y(a+b*mx)-20,'C = C̄ + MPC × Y',purple);s+=point(x(be),y(be),'B: C = Y; S = 0');s+=txt(75,y(a)-10,'C̄ = '+a,purple);s+=txt(110,310,'Dissaving: C > Y',red)+txt(400,310,'Saving: C < Y',green);return svg(s,'Consumption function: positive autonomous consumption, slope MPC and break-even where C equals income.')}
function saving(a=80,b=.75){let be=a/(1-b),mx=Math.max(800,be*1.4),zero=240,scale=160/Math.max(a,(1-b)*mx-a,1),x=Y=>65+540*Y/mx,y=S=>zero-scale*S;let s=`<path d="M65 25V345M65 ${zero}H610" fill="none" stroke="${grey}" stroke-width="1.5" marker-end="url(#arrow)"/>${txt(70,18,'Saving (S)')}${txt(440,375,'Income (Y)')}${txt(43,zero+5,'0')}`;s+=line(65,y(-a),x(mx),y(-a+(1-b)*mx),green);s+=point(x(be),zero,'B: S = 0');s+=txt(75,y(-a)-10,'−C̄ = −'+a,red)+txt(380,60,'S = −C̄ + MPS × Y',green)+txt(390,85,'MPS = '+(1-b).toFixed(2),green);return svg(s,'Saving function: negative autonomous intercept, slope MPS, and zero saving at break-even income.')}
function si(a=80,b=.75,I=100){let eq=(a+I)/(1-b),mx=eq*1.5,max=(1-b)*mx,zero=280,scale=200/(max+a),x=Y=>65+540*Y/mx,y=V=>zero-scale*V;let s=`<path d="M65 25V350M65 ${zero}H610" fill="none" stroke="${grey}" stroke-width="1.5"/>${txt(70,18,'Planned saving and investment')}${txt(440,378,'Income (Y)')}`;s+=line(65,y(-a),x(mx),y(-a+(1-b)*mx),green)+txt(490,y(-a+(1-b)*mx)-10,'S',green);s+=line(65,y(I),605,y(I),purple)+txt(550,y(I)-10,'I',purple);s+=point(x(eq),y(I),'E: S = I');s+=line(x(eq),y(I),x(eq),zero,grey,'4 5')+txt(x(eq)-20,zero+23,'Y* = '+Math.round(eq));return svg(s,'Saving–investment equilibrium: rising planned saving intersects horizontal autonomous investment.')}
function forex(shift=0,type='demand'){let D=200+(type==='demand'?shift:0),S=20+(type==='supply'?shift:0),eq=(D-S)/3,Q=S+eq;const x=q=>65+3*q,y=e=>330-3*e;let s=axes('Exchange rate (₹ per $)','Quantity of US dollars');s+=line(x(0),y(100),x(180),y(10),grey)+txt(x(175),y(12),'D₀',grey);s+=line(x(20),y(0),x(120),y(100),grey)+txt(x(120),y(100)-10,'S₀',grey);if(type==='demand')s+=line(x(0),y(D/2),x(170),y((D-170)/2),purple)+txt(x(165),y((D-170)/2)-10,'D₁',purple);else s+=line(x(S),y(0),x(S+100),y(100),green)+txt(x(S+100),y(100)-10,'S₁',green);s+=point(x(Q),y(eq),'E₁');s+=line(65,y(eq),x(Q),y(eq),purple,'4 5')+txt(12,y(eq)+5,eq.toFixed(0),purple);s+=point(x(80),y(60),'E₀');return svg(s,'Foreign exchange diagram: downward dollar demand and upward dollar supply; '+type+' shifts and changes the equilibrium rupees-per-dollar rate.')}
function circular(){return svg(`<rect x="50" y="140" width="180" height="100" rx="12" fill="#efe9f7" stroke="#c4b1df"/><rect x="410" y="140" width="180" height="100" rx="12" fill="#e8f3ed" stroke="#9fd1bb"/>${txt(90,185,'Households',purple,19)}${txt(475,185,'Firms',green,19)}${txt(82,210,'Own factor services')}${txt(433,210,'Produce goods & services')}<path d="M140 140V65H500V140" stroke="${purple}" stroke-width="2" fill="none" marker-end="url(#arrow)"/><path d="M410 165H230" stroke="${green}" stroke-width="2" marker-end="url(#arrow)"/><path d="M230 220H410" stroke="${purple}" stroke-width="2" marker-end="url(#arrow)"/><path d="M500 240V315H140V240" stroke="${green}" stroke-width="2" fill="none" marker-end="url(#arrow)"/>${txt(190,51,'Factor services → (real flow)',purple)}${txt(245,151,'← Factor incomes',green)}${txt(242,244,'Expenditure →',purple)}${txt(192,341,'← Goods & services (real flow)',green)}`,'Two-sector circular flow: households supply factor services to firms, firms pay incomes; households pay expenditure and firms supply goods.')}
function bridge(){return svg(`<rect x="30" y="40" width="580" height="65" rx="10" fill="#efe9f7"/>${txt(50,80,'GDP at market price',purple,22)}<path d="M320 105V145" stroke="${grey}" marker-end="url(#arrow)"/>${txt(350,132,'− Depreciation')}<rect x="30" y="145" width="580" height="55" rx="10" fill="#f3f1ec"/>${txt(50,180,'NDP at market price',grey,20)}<path d="M320 200V240" stroke="${grey}" marker-end="url(#arrow)"/>${txt(350,226,'− Net indirect taxes')}<rect x="30" y="240" width="580" height="55" rx="10" fill="#f3f1ec"/>${txt(50,275,'NDP at factor cost',grey,20)}<path d="M320 295V335" stroke="${grey}" marker-end="url(#arrow)"/>${txt(350,322,'+ NFIA')}<rect x="30" y="335" width="580" height="50" rx="10" fill="#e8f3ed"/>${txt(50,368,'NNP at factor cost = National income',green,20)}`,'National-income conversion: GDPMP minus depreciation minus NIT plus NFIA gives NNPFC.')}
window.DIAGRAMS={demand,consumption,saving,si,forex,circular,bridge};})();
// Square plot scales keep the Y = X reference line at a true 45 degrees.
(()=>{const P='#7255a4',R='#bb6c53',T='#8b8c87',C='#2f8f6b';const text=(x,y,t,col=T)=>`<text x="${x}" y="${y}" fill="${col}" font-size="12" font-family="system-ui,sans-serif">${t}</text>`,line=(x1,y1,x2,y2,c,d='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="2" ${d?`stroke-dasharray="${d}"`:''}/>`;function wrap(inner,title){return `<svg class="diagram" viewBox="0 0 460 390" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${title}"><title>${title}</title>${inner}</svg>`}function axes(label='Expenditure / output'){return `<path d="M65 30V330H405" fill="none" stroke="${T}" stroke-width="1.4"/>${text(44,348,'0')}${text(245,375,'Income / output (Y)')}${text(65,18,label)}`}const dot=(x,y)=>`<circle cx="${x}" cy="${y}" r="4" fill="${P}"/>`;
window.DIAGRAMS.consumption=(a=80,b=.75)=>{let be=a/(1-b),mx=Math.max(800,be*1.45),x=v=>65+280*v/mx,y=v=>330-280*v/mx;let s=axes('Consumption (C)')+line(65,330,x(mx),y(mx),T)+text(x(mx)-35,y(mx)-12,'C = Y')+line(65,y(a),x(mx),y(a+b*mx),P)+text(x(mx)-80,y(a+b*mx)+24,'C = C̄ + bY',P)+dot(x(be),y(be))+text(x(be)+8,y(be)-10,'B: C = Y',P)+line(x(be),y(be),x(be),330,T,'4 5')+text(x(be)-20,350,'Y = '+be.toFixed(0))+text(72,y(a)-10,'C̄ = '+a,P)+text(85,315,'C > Y',R)+text(270,315,'C < Y',C)+text(83,321,'45°');return wrap(s,'Consumption function and a true 45-degree C = Y reference line. Break-even occurs where the curves intersect.')};
window.DIAGRAMS.saving=(a=80,b=.75)=>{let be=a/(1-b),mx=Math.max(800,be*1.45),ext=Math.max(a,(1-b)*mx-a),zero=190,scale=140/ext,x=v=>65+280*v/mx,y=v=>zero-scale*v;let s=`<path d="M65 25V350M65 ${zero}H405" fill="none" stroke="${T}"/>${text(65,18,'Saving (S)')}${text(280,375,'Income (Y)')}${text(45,zero+5,'0')}`+line(65,y(-a),x(mx),y(-a+(1-b)*mx),C)+dot(x(be),zero)+text(x(be)+8,zero-10,'B: S = 0',P)+text(72,Math.min(y(-a)-10,345),'−C̄ = −'+a,R)+text(205,45,'S = −C̄ + (1 − b)Y',C)+text(205,66,'Slope = MPS = '+(1-b).toFixed(2),C);return wrap(s,'Saving function: negative autonomous intercept, slope MPS and break-even where saving is zero.')};
window.DIAGRAMS.demand=(a=100,b=.75,I=100,Yf=800,gap=false)=>{let eq=(a+I)/(1-b),mx=Math.max(eq,Yf)*1.4,x=v=>65+280*v/mx,y=v=>330-280*v/mx;let s=axes()+line(65,330,x(mx),y(mx),T)+text(x(mx)-45,y(mx)-12,'AS = Y')+line(65,y(a+I),x(mx),y(a+I+b*mx),P)+text(x(mx)-75,y(a+I+b*mx)+24,'AD = C + I',P)+dot(x(eq),y(eq))+text(x(eq)-15,y(eq)-14,'E',P)+line(x(eq),y(eq),x(eq),330,T,'4 5')+text(x(eq)-22,350,'Y* '+eq.toFixed(0))+text(82,320,'45°');if(gap){let ad=a+I+b*Yf;s+=line(x(Yf),y(Math.max(ad,Yf)),x(Yf),330,T,'4 5')+line(x(Yf),y(ad),x(Yf),y(Yf),R)+dot(x(Yf),y(Yf))+text(x(Yf)+9,y(Yf)+16,'F',R)+text(90,30,'Gap at Yf = '+Math.abs(ad-Yf).toFixed(0),R)+text(x(Yf)-18,366,'Yf '+Yf)}return wrap(s,'AD–AS equilibrium with a true 45-degree AS = Y line. '+(gap?'The gap is the vertical difference at full employment, marked F.':''))};
})();
